package main

type Result struct {
	Key         string
	Payload     int
	ProcessedAt int64
}

type effect struct {
	Key     string
	Payload int
}

type Processor struct {
	Window  int64
	Effects []effect
}

func NewProcessor(window int64) *Processor {
	return &Processor{Window: window}
}

func (p *Processor) Process(key string, payload int, now int64) Result {
	p.Effects = append(p.Effects, effect{Key: key, Payload: payload})
	return Result{Key: key, Payload: payload, ProcessedAt: now}
}

test_setup_files.processor_test.go:
package main

import "testing"

func TestDuplicateKeyWithinWindowNotReexecuted(t *testing.T) {
	p := NewProcessor(10)
	first := p.Process("order-1", 5, 0)
	second := p.Process("order-1", 999, 5)
	if second != first {
		t.Fatalf("expected duplicate call to return original result")
	}
	if len(p.Effects) != 1 {
		t.Fatalf("expected 1 effect, got %d", len(p.Effects))
	}
}

func TestDifferentKeysBothExecute(t *testing.T) {
	p := NewProcessor(10)
	p.Process("a", 1, 0)
	p.Process("b", 2, 0)
	if len(p.Effects) != 2 {
		t.Fatalf("expected 2 effects, got %d", len(p.Effects))
	}
}

func TestReexecutesAfterWindowExpires(t *testing.T) {
	p := NewProcessor(10)
	p.Process("order-1", 5, 0)
	p.Process("order-1", 5, 9)
	if len(p.Effects) != 1 {
		t.Fatalf("expected 1 effect before window expiry, got %d", len(p.Effects))
	}
	p.Process("order-1", 7, 10)
	if len(p.Effects) != 2 {
		t.Fatalf("expected 2 effects after window expiry, got %d", len(p.Effects))
	}
	if p.Effects[1].Payload != 7 {
		t.Fatalf("expected fresh payload 7, got %d", p.Effects[1].Payload)
	}
}

