package main

type Result struct {
	Key         string
	Payload     int
	ProcessedAt int64
}

type effect struct {
	Key     string
	Payload int
}

type seen struct {
	result     Result
	recordedAt int64
}

type Processor struct {
	Window  int64
	Effects []effect
	seen    map[string]seen
}

func NewProcessor(window int64) *Processor {
	return &Processor{Window: window, seen: make(map[string]seen)}
}

func (p *Processor) Process(key string, payload int, now int64) Result {
	if cached, ok := p.seen[key]; ok {
		if now-cached.recordedAt < p.Window {
			return cached.result
		}
	}
	p.Effects = append(p.Effects, effect{Key: key, Payload: payload})
	result := Result{Key: key, Payload: payload, ProcessedAt: now}
	p.seen[key] = seen{result: result, recordedAt: now}
	return result
}

