package main

type Result struct {
	Key         string
	Payload     int
	ProcessedAt int64
}

type effect struct {
	Key     string
	Payload int
}

type Processor struct {
	Window  int64
	Effects []effect
	seen    map[string]Result
}

func NewProcessor(window int64) *Processor {
	return &Processor{Window: window, seen: make(map[string]Result)}
}

func (p *Processor) Process(key string, payload int, now int64) Result {
	if cached, ok := p.seen[key]; ok {
		return cached
	}
	p.Effects = append(p.Effects, effect{Key: key, Payload: payload})
	result := Result{Key: key, Payload: payload, ProcessedAt: now}
	p.seen[key] = result
	return result
}
